import { copyFileSync, existsSync, mkdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// Entry point for the make.fun sandbox: deliver the pre-rendered front page.
// The image itself is generated by build_image.py (Python + Pillow) and
// committed as entry.png next to this file; this script copies it into the
// directory the platform reads results from ($MAKEFUN_OUTPUT_DIR), then
// verifies the copy byte-for-byte so a truncated write can never ship.
const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "entry.png");
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? join(here, "output");
const dest = join(outDir, "entry.png");

if (!existsSync(src)) {
  throw new Error(`entry.png not found next to main.ts (looked in ${here})`);
}
mkdirSync(outDir, { recursive: true });
copyFileSync(src, dest);

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
const copied = readFileSync(dest);
const srcBytes = statSync(src).size;
const signatureOk = PNG_SIGNATURE.every((byte, i) => copied[i] === byte);
if (!signatureOk || copied.length !== srcBytes) {
  throw new Error(
    `copy verification failed: dest is ${copied.length} bytes (source ${srcBytes}), PNG signature ${signatureOk ? "ok" : "BAD"}`,
  );
}
console.log(`copied ${src} -> ${dest} (${copied.length} bytes, PNG signature verified)`);
